param([switch]$Force, [switch]$Check)
$ErrorActionPreference = "Stop"

# Run from the ROOT of your NaijaDrops checkout (the folder with package.json).
if (-not (Test-Path -LiteralPath "package.json")) {
    Write-Host "ERROR: package.json not found. Run this from the root of your NaijaDrops checkout." -ForegroundColor Red
    exit 1
}

function Get-NormalizedHash {
    param([string]$path, [bool]$binary)
    $bytes = [System.IO.File]::ReadAllBytes($path)
    if (-not $binary) {
        $text = [System.Text.Encoding]::UTF8.GetString($bytes).TrimStart([char]0xFEFF) -replace "`r`n", "`n"
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($text)
    }
    $sha = [System.Security.Cryptography.SHA256]::Create()
    return (($sha.ComputeHash($bytes) | ForEach-Object { $_.ToString("x2") }) -join "")
}

Write-Host ""
Write-Host "=== NaijaDrops Wallet: top up, pay in one tap, instant refunds ===" -ForegroundColor Cyan

$items = @(
    @{ Path = "supabase/migrations/20261018120000_customer_wallet.sql"; Label = "Repo copy of the wallet migration (already applied to your database)"; Binary = $false; Sha = ""; B64 = "" },
    @{ Path = "src/utils/wallet.js"; Label = "NEW: wallet limits and labels"; Binary = $false; Sha = ""; B64 = "" },
    @{ Path = "src/app/api/wallet/verify-topup/route.js"; Label = "NEW: confirms a Paystack top-up and credits the wallet"; Binary = $false; Sha = ""; B64 = "" },
    @{ Path = "src/app/api/wallet/pay-order/route.js"; Label = "NEW: pays an order from the wallet in one transaction"; Binary = $false; Sha = ""; B64 = "" },
    @{ Path = "src/app/api/verify-payment/route.js"; Label = "A wallet top-up can no longer also pay for an order"; Binary = $false; Sha = "5ed031add7675d6ff3f5b597265aaaa3aa08c9371a786428e26f92bc8e9a35ef"; B64 = "" },
    @{ Path = "src/app/api/webhooks/paystack/route.js"; Label = "Credits top-ups if the browser closed; same double-use guard; webhook-first payments now get a delivery PIN"; Binary = $false; Sha = "1498c19d56177e9cfee0774ddf12d7f18c4a235e8ce1c6edeaf1e74c888253c2"; B64 = "" },
    @{ Path = "src/app/api/account/delete/route.js"; Label = "Cannot delete an account that still holds wallet money"; Binary = $false; Sha = "03c2a662066130834ba22f8ee5c42c5c43df3de7a6ea51f8570e6e58afc5234c"; B64 = "" },
    @{ Path = "src/app/wallet/page.jsx"; Label = "NEW: wallet page (balance, top-up, history)"; Binary = $false; Sha = ""; B64 = "" },
    @{ Path = "src/components/layout/WalletChip.jsx"; Label = "NEW: balance chip in the navbar"; Binary = $false; Sha = ""; B64 = "" },
    @{ Path = "src/components/layout/Navbar.jsx"; Label = "Shows the wallet chip"; Binary = $false; Sha = "889422d57cf8c1b5172e34196b1c8822a921bd24948ad54b1d2d42b42b6ff678"; B64 = "" },
    @{ Path = "src/app/payment/page.jsx"; Label = "Pay with wallet in one tap, or top up the shortfall"; Binary = $false; Sha = "3173428967e62f85a428d7cc28e1e2233e1afef721f2640019db305a3431b074"; B64 = "" },
    @{ Path = "src/app/ops-terminal/payments/page.jsx"; Label = "Ops: total money held in wallets and a ledger self-check"; Binary = $false; Sha = "8255701d2a7a54300a587356c0b036ec017b28c61b7d9761075feedfece128e3"; B64 = "" }
)

# Preflight: refuse to touch a file you have changed since this patch was prepared.
$changed = @()
foreach ($it in $items) {
    if ((Test-Path -LiteralPath $it.Path) -and $it.Sha) {
        if ((Get-NormalizedHash -path $it.Path -binary $it.Binary) -ne $it.Sha) { $changed += $it.Path }
    }
}
if ($changed.Count -gt 0 -and -not $Force) {
    Write-Host "STOPPED - these files differ from the version this patch was built against:" -ForegroundColor Yellow
    $changed | ForEach-Object { Write-Host "  $_" -ForegroundColor Yellow }
    Write-Host "Nothing was changed. If you are sure, re-run with -Force (backups are still written)." -ForegroundColor Yellow
    exit 2
}

# Dry-run the in-place patches now, so a failure stops everything before any file is written.
$patched = @{}
$patchFailed = @()
foreach ($it in $items) {
    if (-not $it.Patch) { continue }
    $pfull = Join-Path (Get-Location).Path $it.Path
    if (-not (Test-Path -LiteralPath $pfull)) { $patchFailed += "$($it.Path) (file not found)"; continue }
    $pbytes = [System.IO.File]::ReadAllBytes($pfull)
    $hasBom = ($pbytes.Length -ge 3 -and $pbytes[0] -eq 0xEF -and $pbytes[1] -eq 0xBB -and $pbytes[2] -eq 0xBF)
    $ptext = [System.Text.Encoding]::UTF8.GetString($pbytes)
    if ($hasBom) { $ptext = $ptext.Substring(1) }
    foreach ($p in $it.Patches) {
        if ([regex]::IsMatch($ptext, $p.Done)) { continue }
        $pnew = [regex]::Replace($ptext, $p.Pattern, $p.Replacement)
        if ($pnew -ceq $ptext) { $patchFailed += "$($it.Path): $($p.Name)" } else { $ptext = $pnew }
    }
    $patched[$it.Path] = @{ Text = $ptext; Bom = $hasBom }
}
if ($patchFailed.Count -gt 0) {
    Write-Host "STOPPED - could not apply these in-place changes (the file looks different from what I expected):" -ForegroundColor Yellow
    $patchFailed | ForEach-Object { Write-Host "  $_" -ForegroundColor Yellow }
    Write-Host "Nothing was changed. Send me the file and I will fix the script." -ForegroundColor Yellow
    exit 3
}
if ($Check) {
    Write-Host "Check passed: every file matches, nothing was changed." -ForegroundColor Green
    exit 0
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path (Get-Location).Path ("WalletV2\_backup\" + $timestamp)
foreach ($it in $items) {
    $full = Join-Path (Get-Location).Path $it.Path
    if ($it.Patch) {
        Write-Host "Patching: $($it.Path)" -ForegroundColor Cyan
        Write-Host "  $($it.Label)"
        $backup = "$full.$timestamp.bak"
        Copy-Item -LiteralPath $full -Destination $backup -Force
        Write-Host "  Backup: $backup" -ForegroundColor Yellow
        $enc = New-Object System.Text.UTF8Encoding($patched[$it.Path].Bom)
        [System.IO.File]::WriteAllText($full, $patched[$it.Path].Text, $enc)
        Write-Host "  Done." -ForegroundColor Green
        continue
    }
    if ($it.Delete) {
        if (Test-Path -LiteralPath $full) {
            $dest = Join-Path $backupRoot $it.Path
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest) | Out-Null
            Copy-Item -LiteralPath $full -Destination $dest -Force
            Remove-Item -LiteralPath $full -Force
            Write-Host "Removed: $($it.Path)" -ForegroundColor Cyan
            # tidy now-empty folders (never above src\app / src\components / src\utils)
            $dir = Split-Path -Parent $full
            while ($dir -and (Test-Path -LiteralPath $dir) -and -not (Get-ChildItem -LiteralPath $dir -Force | Select-Object -First 1)) {
                if ($dir -match '\\src\\(app|components|utils)$') { break }
                Remove-Item -LiteralPath $dir -Force
                $dir = Split-Path -Parent $dir
            }
        } else {
            Write-Host "Already gone: $($it.Path)" -ForegroundColor DarkGray
        }
        continue
    }
    Write-Host "Writing: $($it.Path)" -ForegroundColor Cyan
    Write-Host "  $($it.Label)"
    if (Test-Path -LiteralPath $full) {
        $backup = "$full.$timestamp.bak"
        Copy-Item -LiteralPath $full -Destination $backup -Force
        Write-Host "  Backup: $backup" -ForegroundColor Yellow
    } else {
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $full) | Out-Null
    }
    [System.IO.File]::WriteAllBytes($full, [System.Convert]::FromBase64String($it.B64))
    Write-Host "  Done." -ForegroundColor Green
}

Write-Host ""
Write-Host "Finished." -ForegroundColor Green
